-- Auto-generated normalized dump from OIP_AgentPOC_DataSample(in).csv
-- Corrected positional mapping for 58-column export (split address + 5 trailing blanks)

BEGIN;

CREATE TABLE IF NOT EXISTS accounts (
  id integer PRIMARY KEY,
  sf_id varchar(18),
  name varchar(255),
  address text,
  created_at varchar(20),
  updated_at varchar(20)
);

CREATE TABLE IF NOT EXISTS customers (
  id char(36) PRIMARY KEY,
  sf_id varchar(255),
  global_customer_name varchar(255),
  global_customer_number varchar(255),
  gcn_type varchar(100),
  status varchar(100),
  cbc_case_safe_id varchar(255),
  created_at timestamp,
  updated_at timestamp
);

CREATE TABLE IF NOT EXISTS opportunities (
  id char(36) PRIMARY KEY,
  name varchar(255),
  sf_case_safe_id varchar(255),
  sales_category varchar(100),
  record_type varchar(100),
  isd_status varchar(100),
  created_at timestamp,
  account_id integer REFERENCES accounts(id),
  customer_id char(36) REFERENCES customers(id)
);

CREATE TABLE IF NOT EXISTS countries (
  id char(36) PRIMARY KEY,
  name varchar(100),
  iso_code varchar(10),
  created_at timestamp
);

CREATE TABLE IF NOT EXISTS country_details (
  id char(36) PRIMARY KEY,
  case_safe_id varchar(255),
  ticketing_country_id char(36) REFERENCES countries(id),
  servicing_country_id char(36) REFERENCES countries(id),
  invoicing_agency varchar(255),
  servicing_agency varchar(255),
  created_at timestamp
);

CREATE TABLE IF NOT EXISTS projects (
  id char(36) PRIMARY KEY,
  name varchar(255),
  project_configuration_id varchar(255),
  opportunity_id char(36) REFERENCES opportunities(id),
  project_country_id char(36) REFERENCES countries(id),
  traveller_country_id char(36) REFERENCES countries(id),
  country_details_id char(36) REFERENCES country_details(id),
  created_at timestamp
);

CREATE TABLE IF NOT EXISTS decision_sources (
  id char(36) PRIMARY KEY,
  case_safe_id varchar(255),
  created_at timestamp
);

CREATE TABLE IF NOT EXISTS service_config (
  id char(36) PRIMARY KEY,
  service_configuration varchar(255),
  service_segmentation varchar(255),
  created_at timestamp
);

CREATE TABLE IF NOT EXISTS solutions (
  id char(36) PRIMARY KEY,
  tool_service_sf_id varchar(255),
  program_solution_case_safe_id varchar(255),
  tool_or_service varchar(255),
  product_type_id varchar(255),
  product_type varchar(255),
  solution_status_id varchar(255),
  solution_status varchar(100),
  record_type varchar(100),
  status_id varchar(255),
  final_status varchar(100),
  created_at timestamp,
  updated_at timestamp,
  account_id integer REFERENCES accounts(id),
  opportunity_id char(36) REFERENCES opportunities(id),
  project_id char(36) REFERENCES projects(id),
  decision_source_id char(36) REFERENCES decision_sources(id),
  service_config_id char(36) REFERENCES service_config(id),
  country_details_id char(36) REFERENCES country_details(id)
);

CREATE TABLE IF NOT EXISTS srq_requests (
  id char(36) PRIMARY KEY,
  srq_number varchar(255),
  srq_name varchar(255),
  service_config_id char(36) REFERENCES service_config(id)
);





